      "path": "src/treg/infra/upstream/relay.py",
      "content": "\"\"\"The relay — a faithful, smart proxy. The whole product in one function.\n\nFaithfulness contract — it alters ONLY these, everything else is relayed verbatim\n(method, path, ALL query params incl. duplicates, caller headers, caller cookies, body bytes streamed):\n  1. transport/hop-by-hop headers — re-derived for the new hop (forwarding stale ones corrupts\n     the stream); httpx sets them correctly upstream.\n  2. treg's own control/infra headers + the edge's forwarding headers (`x-treg-*`,\n     `ngrok-skip-browser-warning`, `x-forwarded-*`, `x-real-ip`, `forwarded`, `via`, Cloudflare's\n     `cf-connecting-ip` family and whatever `TREG_CLIENT_IP_HEADER` names) — stripped so they never\n     leak upstream. A Cloudflare-fronted provider refuses any request still carrying one with 403\n     error 1000 (\"DNS points to prohibited IP\"), and the MCP layer forwards the caller's address\n     to treg's own API in that header, so every MCP call to such a provider would fail. treg's own cookies (`treg_session`, `treg_oauth_state`) are scrubbed\n     from the Cookie header too (the dashboard's `credentials:'include'` Try-it would otherwise leak\n     our session token to the upstream); any other caller cookies are preserved.\n  3. the credential(s) the tool's bindings inject — overwrite only their target header, query\n     parameter or top-level JSON field. A JSON binding buffers, parses and reserializes the object;\n     it is semantic JSON relay, not byte-faithful, and is forbidden for raw-body-signature APIs.\n  4. on treg's SHARED key only (tier 4), the caller's `Idempotency-Key` is re-scoped per org by\n     `scope_shared_idempotency_key` before the request is built. Every org shares one provider\n     account there, so a provider that honors the header would hand org B the job org A created\n     under the same label — and the ownership record would then make B its owner (reproduced live\n     against LeadsForge, 2026-09-09). The caller loses nothing: treg's own idempotency table already\n     replays their answer for the same label. A team's own key relays the header verbatim.\n  5. on treg's SHARED key only, the caller's `User-Agent` is replaced by treg's own\n     (`TREG_USER_AGENT`, by `identify_as_treg`). The provider sees treg's account there, and a\n     library default such as Python's is read as bot traffic: Cloudflare rules answered 403 (error\n     1010) to every `Python-urllib` call on LimaData, and to Wiza's phone reveals for a day, both on\n     treg's key. A team's own key relays the caller's header verbatim.\n  6. on treg's SHARED key only, when the provider's catalog file names a `client_header` and\n     `TREG_CLIENT_ID_SECRET` is set, that header carries treg's opaque code for the calling team\n     (`tag_shared_client`): HMAC-SHA256 of the secret over (provider, team), so the provider can\n     split usage, errors and cost per customer on treg's one account without learning who the\n     customer is, and two providers' codes for one team do not match. Any value the caller sent\n     under that name is replaced. A team's own key relays the caller's headers verbatim.\n\nExcept for that explicit JSON-binding contract, it never buffers the body (rule 5: stream, don't\nduplicate) and uses the shared long-lived httpx client (rule 1: keepalive). Secrets are passed\nalready-loaded (api does the DB work).\n\"\"\"\n\nfrom __future__ import annotations\n\nimport asyncio\nimport hashlib\nimport hmac\nimport json\nfrom collections.abc import Awaitable, Callable\nfrom contextvars import ContextVar\n\nimport httpx\n\nfrom ... import crypto, jsontext, oauth_providers\nfrom ...application.call.types import GatewayFailed, UpstreamRequest, UpstreamResponse\nfrom ...config import TREG_USER_AGENT, get_settings\nfrom ...models import Secret, Tool\nfrom . import injectors\n\n# Connection-level headers that belong to a single hop and must NOT be forwarded as-is.\n_HOP_BY_HOP = frozenset(\n    {\n        \"host\", \"content-length\", \"connection\", \"keep-alive\", \"proxy-authenticate\",\n        \"proxy-authorization\", \"te\", \"trailers\", \"transfer-encoding\", \"upgrade\",\n    }\n)\n# The edge's forwarding headers + third-party infra — never leak to the upstream. treg's OWN headers\n# are handled by the `x-treg-` PREFIX rule below, not by name, so the next one added is covered too.\n_CONTROL = frozenset(\n    {\n        \"ngrok-skip-browser-warning\",\n        \"x-forwarded-for\", \"x-forwarded-proto\", \"x-forwarded-host\", \"x-forwarded-port\",\n        \"x-real-ip\", \"forwarded\", \"via\",\n        # The headers Cloudflare's edge adds on the way in (and the MCP layer re-sends in process).\n        \"cf-connecting-ip\", \"cf-connecting-ipv6\", \"cf-pseudo-ipv4\", \"true-client-ip\",\n        \"cf-ipcountry\", \"cf-ray\", \"cf-visitor\", \"cf-worker\", \"cf-ew-via\", \"cdn-loop\",\n    }\n)\n_TREG_PREFIX = \"x-treg-\"\n_DROP_REQUEST = _HOP_BY_HOP | _CONTROL\n\n\ndef _is_dropped_request_header(name: str, extra: frozenset[str]) -> bool:\n    \"\"\"Whether a caller header is ours/hop-by-hop and must not reach the upstream.\"\"\"\n    return (name in _DROP_REQUEST or name in extra or name.startswith(_TREG_PREFIX)\n            or name == get_settings().client_ip_header.strip().lower())\n\n\n_IDEMPOTENCY_HEADER = b\"idempotency-key\"\n\n\ndef _unique_json_object(pairs: list[tuple[str, object]]) -> dict[str, object]:\n    \"\"\"Build an object while refusing ambiguous duplicate keys before credential injection.\"\"\"\n    result: dict[str, object] = {}\n    for name, value in pairs:\n        if name in result:\n            raise ValueError(f\"duplicate JSON object key: {name}\")\n        result[name] = value\n    return result\n\n\ndef identify_as_treg(raw_headers: tuple[tuple[bytes, bytes], ...]) -> tuple[tuple[bytes, bytes], ...]:\n    \"\"\"Rewrite 5 of the faithfulness contract: on treg's shared key the caller's User-Agent becomes\n    treg's own (see the module docstring for the providers that blocked library defaults).\"\"\"\n    kept = tuple((k, v) for k, v in raw_headers if k.lower() != b\"user-agent\")\n    return kept + ((b\"user-agent\", TREG_USER_AGENT.encode()),)\n\n\ndef shared_client_code(secret: str, provider: str, org_id: int) -> str:\n    \"\"\"treg's opaque code for one team at one provider: stable per (provider, team), not reversible\n    without the secret, and different at every provider.\"\"\"\n    mac = hmac.new(secret.encode(), f\"{provider}\\x1f{org_id}\".encode(), hashlib.sha256)\n    return \"t_\" + mac.hexdigest()[:24]\n\n\ndef tag_shared_client(\n    raw_headers: tuple[tuple[bytes, bytes], ...], header: str | None, provider: str, org_id: int,\n) -> tuple[tuple[bytes, bytes], ...]:\n    \"\"\"Rewrite 6 of the faithfulness contract: on treg's shared key, the provider's declared client\n    header carries treg's code for the team. Nothing changes when the provider declares no header\n    or the secret is unset.\"\"\"\n    secret = get_settings().client_id_secret\n    if not header or not secret:\n        return raw_headers\n    name = header.lower().encode()\n    kept = tuple((k, v) for k, v in raw_headers if k.lower() != name)\n    return kept + ((name, shared_client_code(secret, provider, org_id).encode()),)\n\n\ndef scope_shared_idempotency_key(\n    raw_headers: tuple[tuple[bytes, bytes], ...], org_id: int,\n    *, pinned_tags: dict | None = None,\n) -> tuple[tuple[bytes, bytes], ...]:\n    \"\"\"Rewrite 4 of the faithfulness contract: partition the caller's idempotency label by org and enforced pin.\n\n    Only for calls on treg's shared provider key. The value is an opaque, fixed-length digest of\n    (org, pin, label): distinct pins do not share a provider dedupe entry. With no pin, the\n    existing (org, label) digest is preserved. The same scope retrying the\n    same label still hits the provider's own dedupe should treg's replay window miss it.\n    \"\"\"\n    scope = f\"{org_id}\\x1f\".encode()\n    if pinned_tags:\n        scope += b\"pins:\" + json.dumps(pinned_tags, sort_keys=True, separators=(\",\", \":\")).encode() + b\"\\x1f\"\n    return tuple(\n        (k, hashlib.sha256(scope + v).hexdigest().encode())\n        if k.lower() == _IDEMPOTENCY_HEADER else (k, v)\n        for k, v in raw_headers\n    )\n_DROP_RESPONSE = _HOP_BY_HOP\n_TREG_COOKIES = frozenset({\"treg_session\", \"treg_oauth_state\"})  # our cookies, scrubbed from Cookie\n\n\ndef _scrub_treg_cookies(headers: httpx.Headers) -> None:\n    \"\"\"Drop treg's own cookies from the forwarded Cookie header so a dashboard `credentials:'include'`\n    call never leaks our session token upstream. Other caller cookies are kept; an emptied header is removed.\"\"\"\n    cookie = headers.get(\"cookie\")\n    if not cookie:\n        return\n    kept = [\n        c.strip() for c in cookie.split(\";\")\n        if c.strip() and c.split(\"=\", 1)[0].strip().lower() not in _TREG_COOKIES\n    ]\n    if kept:\n        headers[\"cookie\"] = \"; \".join(kept)\n    else:\n        del headers[\"cookie\"]\n\n\n\n# Set by a caller that needs to know the request actually left: called once every local check\n# above has passed, immediately before the send. Not called for a request refused here.\nON_SEND: ContextVar[Callable[[], None] | None] = ContextVar(\"relay_on_send\", default=None)\n\nasync def relay(\n    request: UpstreamRequest,\n    upstream_url: str,\n    tool: Tool,\n    secrets: dict[int, Secret],\n    client: httpx.AsyncClient,\n    drop_params: set[str] | None = None,\n    force_identity: bool = False,\n    before_outbound: Callable[[], Awaitable[None]] | None = None,\n) -> UpstreamResponse:\n    # Headers: preserve everything (incl. duplicates / cookies) except hop-by-hop + our token.\n    # `.raw` is the original (bytes, bytes) pairs; httpx.Headers is a multidict, so binding\n    # injection (headers[name]=v) overwrites only its target and leaves the rest untouched.\n    # RFC 7230 §6.1: also drop any header NAMED in the caller's own Connection header.\n    req_drop = _connection_named(_header_value(request.raw_headers, \"connection\"))\n    headers = httpx.Headers(\n        [(k, v) for k, v in request.raw_headers\n         if not _is_dropped_request_header(k.decode(\"latin-1\").lower(), req_drop)]\n    )\n    _scrub_treg_cookies(headers)  # keep caller cookies, drop treg's own session cookie\n    # The body is relayed RAW (aiter_raw), and httpx adds its own `Accept-Encoding: gzip,...` when\n    # the request has none: ask for identity so a caller never gets gzip it did not ask for.\n    if \"accept-encoding\" not in headers:\n        headers[\"accept-encoding\"] = \"identity\"\n    # Metered marketplace calls OVERRIDE the caller's choice: the settle path must json-parse the\n    # buffered body for the provider's own reported charge, and a caller-requested gzip would hand\n    # it compressed bytes, and the charge would silently fall back to the estimate.\n    if force_identity:\n        headers[\"accept-encoding\"] = \"identity\"\n    # Query: a list of pairs preserves duplicate keys verbatim (?tag=a&tag=b). A marketplace\n    # endpoint-id call may have CONSUMED some params into the path (`{siteUrl}` placeholders) —\n    # those must not also reach the upstream as query noise. The call application may already\n    # have appended a catalog ceiling_param the caller did not send; it is forwarded like any\n    # other query param.\n    params: list[tuple[str, str]] = [\n        (k, v) for k, v in request.query_items\n        if not drop_params or k not in drop_params\n    ]\n\n    json_bindings = any(binding.get(\"location\") == \"json\" for binding in tool.bindings)\n    json_body: dict[str, object] | None = None\n    if json_bindings:\n        if not request.has_body or request.body_read is None:\n            raise GatewayFailed(\n                \"injection_failed\", status_code=502,\n                detail=\"JSON credential injection requires a readable request body\")\n        try:\n            parsed = json.loads(await request.body_read(), object_pairs_hook=_unique_json_object)\n        except ValueError as exc:\n            raise GatewayFailed(\n                \"injection_failed\", status_code=502,\n                detail=\"JSON credential injection requires valid JSON with unique object keys\") from exc\n        if not isinstance(parsed, dict):\n            raise GatewayFailed(\n                \"injection_failed\", status_code=502,\n                detail=\"JSON credential injection requires a JSON object request body\")\n        json_body = parsed\n\n    # Apply every binding (a request may need several credentials at once).\n    for binding in tool.bindings:\n        # A PLATFORM binding injects one of treg's own credentials (Google Ads' developer token),\n        # read from settings rather than an org secret. Keeping it out of the org's secret store\n        # matters: it's treg's credential, not the tenant's, so it must not be readable by them or\n        # extractable through a local run.\n        setting = binding.get(\"platform_setting\")\n        if setting:\n            value = get_settings().platform_credential(setting, binding.get(\"account\"))\n            if not value:\n                raise GatewayFailed(\n                    \"injection_failed\", status_code=502,\n                    detail=f\"this server has no {setting} configured\")\n            try:\n                injectors.inject(headers, params, binding, value, json_body=json_body)\n            except ValueError as exc:\n                raise GatewayFailed(\n                    \"injection_failed\", status_code=502,\n                    detail=f\"credential injection failed: {exc}\") from exc\n            continue\n        secret = secrets[binding[\"secret_id\"]]\n        raw = crypto.decrypt(secret.value)\n        try:\n            injectors.inject(headers, params, binding, raw, json_body=json_body)\n        except ValueError as exc:\n            raise GatewayFailed(\n                \"injection_failed\", status_code=502,\n                detail=f\"credential injection failed: {exc}\") from exc\n        # Part of the injected credential on treg's Meta app: the HMAC pairing its token with the app.\n        if proof := oauth_providers.connection_appsecret_proof(secret, binding, raw, upstream_url):\n            params[:] = [(k, v) for (k, v) in params if k != \"appsecret_proof\"]\n            params.append((\"appsecret_proof\", proof))\n\n    # Only carry a body when the caller actually sent one — otherwise passing an (unsized) stream\n    # makes httpx frame the request `Transfer-Encoding: chunked`, putting a bogus body-frame on a\n    # GET/HEAD/OPTIONS (which strict upstreams reject).\n    content = (jsontext.dumps_bytes(json_body, separators=(\",\", \":\"))\n               if json_body is not None else request.body_stream() if request.has_body else None)\n    # A streamed body with no length makes httpx frame it `Transfer-Encoding: chunked`. The bytes are\n    # the caller's, unaltered, so the caller's own Content-Length is exact — carry it, and httpx\n    # frames the upstream request with it instead. Meta's Graph API edge does not read a chunked\n    # request body: every JSON/form/multipart POST arrived as a bodyless request, and an ad creative\n    # sent that way failed \"Ad incomplete\". A caller who streamed chunked stays chunked.\n    if json_body is not None:\n        headers[\"content-length\"] = str(len(content))\n    elif content is not None and (cl := _header_value(request.raw_headers, \"content-length\")):\n        headers[\"content-length\"] = cl\n    # Merge the query onto the URL rather than passing params=: httpx REPLACES a URL's existing\n    # query whenever params is given (even an empty list), which silently stripped a catalog path's\n    # own query — LinkedIn's `/rest/images?action=initializeUpload`, Facebook's `?is_hidden=true`.\n    # Same trap, same fix as the health probe (health.py).\n    url = httpx.URL(upstream_url)\n    for k, v in params:\n        url = url.copy_add_param(k, v)\n    upstream_req = client.build_request(request.method, url, headers=headers, content=content)\n    # Call-time SSRF guard: resolve the upstream host NOW and refuse an internal target — defeats DNS\n    # rebinding (base_url was public at registration, its DNS now points at 169.254.169.254 / localhost).\n    from . import health\n    if get_settings().proxy_ssrf_check and not health.host_is_public(upstream_req.url.host):\n        raise GatewayFailed(\n            \"ssrf_refused\", status_code=502,\n            detail=\"upstream host resolves to a non-public address\")\n    if before_outbound is not None:\n        await before_outbound()\n    if (on_send := ON_SEND.get()) is not None:\n        on_send()\n    upstream_resp = await client.send(upstream_req, stream=True)\n\n    # Response drop set: hop-by-hop + whatever the upstream marked hop-by-hop via its Connection\n    # header. Keep upstream Content-Length on a bodyless reply (HEAD/204/304) — that's the whole\n    # point of HEAD; for a normal GET we re-frame so it's dropped.\n    drop_resp = _DROP_RESPONSE | _connection_named(upstream_resp.headers.get(\"connection\"))\n    if request.method == \"HEAD\" or upstream_resp.status_code in (204, 304):\n        drop_resp = drop_resp - {\"content-length\"}\n    # Relay every remaining upstream header verbatim (incl. multiple Set-Cookie), EXCEPT a\n    # Set-Cookie for one of treg's own cookies — a registered upstream must not be able to\n    # overwrite the operator's treg_session / treg_oauth_state under treg's origin (fixation).\n    raw_headers = [\n        (k.encode(\"latin-1\"), v.encode(\"latin-1\"))\n        for k, v in upstream_resp.headers.multi_items()\n        if k.lower() not in drop_resp and not _is_treg_setcookie(k, v)\n    ]\n    # A browser navigating to /call/... must not render upstream HTML as an active document under\n    # treg's origin (reflected XSS with the session cookie). Agents ignore both headers.\n    raw_headers.append((b\"x-content-type-options\", b\"nosniff\"))\n    raw_headers.append((b\"content-security-policy\", b\"sandbox\"))\n    return UpstreamResponse(\n        status=upstream_resp.status_code,\n        raw_headers=tuple(raw_headers),\n        body_stream=upstream_resp.aiter_raw(),\n        close=_close_once(upstream_resp.aclose),\n    )\n\n\ndef _close_once(close: Callable[[], Awaitable[None]]) -> Callable[[], Awaitable[None]]:\n    \"\"\"Join one close task even when its caller is cancelled or invokes cleanup repeatedly.\"\"\"\n    task: asyncio.Task[None] | None = None\n\n    async def close_once() -> None:\n        nonlocal task\n        if task is None:\n            task = asyncio.create_task(close())\n        interrupted = False\n        while not task.done():\n            try:\n                await asyncio.shield(task)\n            except asyncio.CancelledError:\n                interrupted = True\n        await task\n        if interrupted:\n            raise asyncio.CancelledError\n\n    return close_once\n\n\ndef _connection_named(conn: str | None) -> frozenset[str]:\n    \"\"\"The header names a peer marked connection-scoped via its `Connection` header (RFC 7230).\"\"\"\n    if not conn:\n        return frozenset()\n    return frozenset(t.strip().lower() for t in conn.split(\",\") if t.strip())\n\n\ndef _header_value(raw_headers: tuple[tuple[bytes, bytes], ...], name: str) -> str | None:\n    wanted = name.encode(\"latin-1\")\n    for key, value in reversed(raw_headers):\n        if key.lower() == wanted:\n            return value.decode(\"latin-1\")\n    return None\n\n\ndef _is_treg_setcookie(name: str, value: str) -> bool:\n    return name.lower() == \"set-cookie\" and value.split(\"=\", 1)[0].strip().lower() in _TREG_COOKIES\n"
    },
    {
      "path": "src/treg/routers/call.py",
      "content": "\"\"\"HTTP adapters for the proxied call surface.\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport uuid\nfrom urllib.parse import urlsplit\n\nfrom fastapi import APIRouter, Depends, HTTPException, Request\nfrom fastapi.responses import Response, StreamingResponse\nfrom sqlalchemy.exc import TimeoutError as PoolTimeoutError\nfrom starlette.background import BackgroundTask\nfrom sqlalchemy.ext.asyncio import AsyncSession\n\nfrom .. import analytics\nfrom .. import audit\nfrom .. import sandbox as demo_sandbox\nfrom ..application.call.access import catalog_endpoint_access as get_catalog_endpoint_access\nfrom ..application.call.idempotency import (\n    _release_idempotent_claim as release_idempotent_claim,\n)\nfrom ..application.call.resolve import (\n    QueryValues,\n    _may_have_body as may_have_body,\n)\nfrom ..application.call.service import (\n    _refusal_kind,\n    _tool_called_props,\n    create_call_context,\n    execute_call,\n)\nfrom ..application.call.invite import invitation\nfrom ..application.call.intake import (\n    META_HEADER,\n    CallMeta,\n    _parse_call_meta as parse_call_meta,\n)\nfrom ..application.call.types import CallerSnapshot, CallFailure, CallInput, UpstreamResponse\nfrom ..caller_metadata import _client_of\nfrom ..call_surface import split_call_path\nfrom ..config import get_settings\nfrom ..domain.catalog import store as catalog_store\nfrom ..domain.governance import access as access_policy\nfrom ..domain.governance import publicdemo as publicdemo_policy\nfrom ..domain.governance import usage as usage_policy\nfrom ..domain.identity.access import Caller, require_member\nfrom ..infra.db import get_session\nfrom ..infra import org_concurrency, org_flow_control, org_traffic\nfrom ..models import Tool\nfrom .auth import _client_ip\n\n\napp = APIRouter()\nrouter = app\n\n\nclass _HttpRequestBody:\n    def __init__(self, request: Request) -> None:\n        self._request = request\n\n    def stream(self):\n        return self._request.stream()\n\n    async def read(self) -> bytes:\n        return await self._request.body()\n\n\nclass _LeasedStreamingResponse(StreamingResponse):\n    \"\"\"Retain the root slot through send/disconnect errors as well as body iteration.\"\"\"\n\n    def __init__(self, response: StreamingResponse, slot, close) -> None:\n        super().__init__(response.body_iterator, status_code=response.status_code,\n                         background=response.background)\n        self.raw_headers = response.raw_headers\n        self._slot = slot\n        self._close = close\n\n    async def __call__(self, scope, receive, send) -> None:\n        try:\n            await super().__call__(scope, receive, send)\n        finally:\n            await self._slot.finish(self._close)\n\n\ndef _http_upstream_response(upstream: UpstreamResponse) -> StreamingResponse:\n    async def body_stream():\n        completed = False\n        try:\n            async for chunk in upstream.body_stream:\n                yield chunk\n            completed = True\n        finally:\n            # A normal stream closes from Starlette's background task after the final ASGI body\n            # frame. Error, disconnect, and cancellation never reach that frame, so close here.\n            if not completed:\n                await upstream.close()\n\n    response = StreamingResponse(\n        body_stream(),\n        status_code=upstream.status,\n        background=BackgroundTask(upstream.close),\n    )\n    response.raw_headers = list(upstream.raw_headers)\n    return response\n\n\ndef _attach_async_descriptor(upstream: UpstreamResponse, context, rest: str = \"\") -> None:\n    \"\"\"Attach static catalog metadata before Starlette starts the upstream body stream.\n\n    An idempotent replay returns before marketplace resolution, so the endpoint is taken from the\n    path itself: a `--await` retry of a stored submission must still learn how to poll the task\n    that is already running, or it would print the body and stop.\"\"\"\n    marketplace = context.marketplace\n    endpoint_id = marketplace.endpoint_id if marketplace is not None else rest.split(\"?\", 1)[0]\n    endpoint = catalog_store.load().by_id.get(endpoint_id)\n    descriptor = endpoint.get(\"async\") if endpoint else None\n    if not descriptor:\n        return\n    value = json.dumps(descriptor, ensure_ascii=True, separators=(\",\", \":\")).encode(\"ascii\")\n    upstream.raw_headers = tuple(\n        (name, existing) for name, existing in upstream.raw_headers\n        if name.lower() != b\"x-treg-async\"\n    ) + ((b\"x-treg-async\", value),)\n\n\ndef _require_tool_use_http(caller: Caller, tool: Tool) -> None:\n    try:\n        access_policy._require_tool_use(caller, tool)\n    except access_policy.AccessPolicyError as exc:\n        raise HTTPException(status_code=403, detail=exc.detail) from exc\n\n\nasync def _enforce_public_demo_ip_cap(request: Request, db: AsyncSession) -> None:\n    try:\n        await publicdemo_policy.enforce_public_demo_ip_cap(_client_ip(request), db)\n    except publicdemo_policy.PublicDemoLimitError as exc:\n        await db.commit()\n        raise HTTPException(status_code=429, detail=exc.detail) from exc\n    await db.commit()\n\n\nasync def _enforce_daily_cap(caller: Caller, db: AsyncSession) -> None:\n    \"\"\"The run surfaces' door to the per-user daily cap - the SAME gate `/call/` goes through\n    (`application/call/authorize.py`), so a member cannot dodge the cap by switching path. Commits,\n    because the gate takes the slot with a write and this request's session is the only owner.\"\"\"\n    try:\n        await usage_policy.enforce_daily_cap(\n            caller, db, sandbox=demo_sandbox.is_sandbox(caller.org))\n    except usage_policy.UsagePolicyError as exc:\n        await db.commit()\n        raise HTTPException(status_code=429, detail=exc.detail) from exc\n    await db.commit()\n\n\ndef _translate_call_failure(exc: CallFailure) -> HTTPException:\n    headers = {\"Retry-After\": str(exc.retry_after_s)} if exc.retry_after_s is not None else None\n    return HTTPException(status_code=exc.status_code, detail=exc.detail, headers=headers)\n\n\ndef _parse_call_meta(request: Request, caller: Caller | None = None) -> CallMeta:\n    try:\n        return parse_call_meta(request.headers.get(META_HEADER), caller)\n    except CallFailure as exc:\n        raise _translate_call_failure(exc) from exc\n\n\nasync def _release_idempotent_claim(request: Request) -> None:\n    claim = getattr(request.state, \"idem_claim\", None)\n    request.state.idem_claim = None\n    await release_idempotent_claim(claim)\n\n\ndef _query_values(request: Request) -> QueryValues:\n    return QueryValues(tuple(request.query_params.multi_items()))\n\n\ndef _may_have_body(request: Request) -> bool:\n    return may_have_body(tuple(request.headers.raw))\n\n\ndef _call_rest(request: Request, context: object | None) -> str:\n    rest = getattr(getattr(context, \"input\", None), \"raw_rest\", None)\n    if rest is not None:\n        return rest\n    call_path = split_call_path(request.url.path)\n    return call_path[1] if call_path else request.url.path.lstrip(\"/\")\n\n\ndef _capture_exceptional_call(\n    request: Request, *, call_ref: str, status_code: int, failure_kind: str,\n) -> None:\n    \"\"\"Mirror a call that never reached the normal audit funnel without leaking request data.\"\"\"\n    context = getattr(request.state, \"call_context\", None)\n    marketplace = getattr(context, \"marketplace\", None)\n    target = getattr(context, \"target\", None)\n    rest = _call_rest(request, context)\n    tool_name = (\n        getattr(marketplace, \"endpoint_id\", None)\n        or getattr(getattr(target, \"tool\", None), \"name\", None)\n        or rest.split(\"/\", 1)[0]\n        or \"-\"\n    )\n    props = _tool_called_props(\n        request,\n        tool_name=tool_name,\n        status_code=status_code,\n        call_ref=call_ref,\n        own_tool=(False if marketplace is not None else True if target is not None else None),\n        refused_by=None,\n        answered=False,\n    ) | {\"failure_kind\": failure_kind, \"provider\": None, \"endpoint_id\": None}\n    if marketplace is not None:\n        props |= {\n            \"provider\": marketplace.provider,\n            \"endpoint_id\": marketplace.endpoint_id,\n            \"tier\": marketplace.tier,\n            \"metered\": marketplace.metered,\n            \"cost_type\": marketplace.cost_type,\n        }\n    elif target is not None:\n        props[\"provider\"] = urlsplit(target.upstream).hostname or \"\"\n    org_id, email = getattr(request.state, \"call_identity\", (None, \"\"))\n    team_slug = getattr(request.state, \"call_team_slug\", \"\")\n    request.state.call_failure_kind = props[\"failure_kind\"]\n    analytics.capture(\n        email or \"anonymous\",\n        \"tool_called\",\n        props,\n        groups={\"team\": team_slug} if org_id is not None and team_slug else None,\n    )\n\n\nasync def _stamp_call_exit(\n    request: Request,\n    resp: Response,\n    status_code: int,\n    *,\n    failure_kind: str | None = None,\n) -> None:\n    \"\"\"Give one call-surface exit the three things every other exit gets: the id that joins the response\n    to the audit row, the row itself, and the release of any idempotency label the request took.\n\n    Shared by the two handlers that answer a call without reaching `call_tool`'s own bookkeeping.\n    Identity comes from `request.state` (stashed at handler entry); an exit that failed before the\n    caller was resolved records an anonymous row, which is still the fact that someone knocked.\"\"\"\n    call_ref = getattr(request.state, \"call_ref\", \"\") or uuid.uuid4().hex\n    request.state.call_ref = call_ref\n    resp.headers[\"X-Treg-Call-Id\"] = call_ref\n    if (cost_micro := getattr(request.state, \"call_cost_micro\", None)) is not None:\n        resp.headers[\"X-Treg-Cost-Micro\"] = str(cost_micro)\n    if not getattr(request.state, \"call_audited\", False):\n        org_id, email = getattr(request.state, \"call_identity\", (None, \"\"))\n        key_id, key_name, key_prefix = getattr(request.state, \"call_key\", (None, None, None))\n        context = getattr(request.state, \"call_context\", None)\n        rest = _call_rest(request, context)\n        audit.record_call(\n            org_id=org_id, user_email=email, tool_name=rest.split(\"/\", 1)[0] or \"—\",\n            method=request.method, path=request.url.path, status_code=status_code,\n            client=_client_of(request), refused_by=_refusal_kind(status_code),\n            api_key_id=key_id, api_key_name=key_name, api_key_prefix=key_prefix,\n            telemetry={\"call_ref\": call_ref, \"tags\": getattr(request.state, \"call_pins\", None)})\n        if failure_kind:\n            _capture_exceptional_call(\n                request, call_ref=call_ref, status_code=status_code, failure_kind=failure_kind)\n        request.state.call_audited = True\n    await _release_idempotent_claim(request)\n\n\n@app.get(\"/catalog/endpoints/{endpoint_id}/access\", include_in_schema=False)\nasync def catalog_endpoint_access(\n    endpoint_id: str, authorization_method: str = \"\",\n    caller: Caller = Depends(require_member), db: AsyncSession = Depends(get_session)\n) -> dict:\n    \"\"\"Translate the catalog access use case into HTTP.\"\"\"\n    try:\n        return await get_catalog_endpoint_access(\n            endpoint_id=endpoint_id,\n            authorization_method=authorization_method,\n            caller=caller,\n            db=db,\n        )\n    except CallFailure as exc:\n        raise _translate_call_failure(exc) from exc\n\ndef _capture_hint(request: Request, context, kind: str) -> None:\n    \"\"\"One event per invitation actually sent, on every surface: the response-rate denominator.\n    Attachment is not display; the surface's `X-Treg-Client` says who was asked.\"\"\"\n    marketplace = context.marketplace\n    slug = context.input.caller.org.slug\n    analytics.capture(analytics.SERVER_DISTINCT_ID, \"hint_attached\", {\n        \"kind\": kind, \"call_id\": context.call_ref, \"client\": _client_of(request),\n        \"endpoint_id\": marketplace.endpoint_id if marketplace is not None else None,\n    }, groups={\"team\": slug} if slug else None)\n\n\n@app.api_route(\n    \"/call/{rest:path}\",\n    methods=[\"GET\", \"POST\", \"PUT\", \"PATCH\", \"DELETE\", \"HEAD\", \"OPTIONS\"],\n)\nasync def call_tool(\n    rest: str,\n    request: Request,\n    caller: Caller = Depends(require_member),\n):\n    prefix = \"/catalog/call/\" if getattr(request.state, \"catalog_only\", False) else \"/call/\"\n    return await run_call_surface(rest, request, caller, prefix=prefix, finish=_relay_answer)\n\n\nasync def _relay_answer(request: Request, context, upstream: UpstreamResponse, rest: str) -> Response:\n    \"\"\"`/call/`'s ending: the provider's answer, streamed unchanged, with the optional invitation.\"\"\"\n    _attach_async_descriptor(upstream, context, rest)\n    response = _http_upstream_response(upstream)\n    try:\n        # Optional invitation, decided before the body streams (application/call/invite.py).\n        kind = await invitation(context, response.status_code,\n                                replayed=bool(response.headers.get(\"X-Treg-Idempotent-Replay\")))\n        if kind is not None:\n            response.headers[\"X-Treg-Hint\"] = kind\n            if kind == \"review\":\n                response.headers[\"X-Treg-Review\"] = \"requested\"  # read by CLI <= 0.18\n            _capture_hint(request, context, kind)\n    except Exception:  # noqa: BLE001 - a fault here can only lose the hint header\n        pass  # A fault here can only lose the header; the answer is already built.\n    if routed := _routed_alternative(context, response.status_code):\n        response.headers[\"X-Treg-Routed-Tool\"] = routed\n    return response\n\n\ndef _routed_alternative(context, status: int) -> str | None:\n    \"\"\"The routed `treg.<capability>` tool for a successful direct call to one provider's endpoint\n    of that capability, so the surfaces can point an agent to the tool that picks the provider and\n    falls back. Never on a routed call itself.\"\"\"\n    marketplace = context.marketplace\n    if marketplace is None or not 200 <= status < 300 or marketplace.endpoint_id.startswith(\"treg.\"):\n        return None\n    by_id = catalog_store.load().by_id\n    capability = (by_id.get(marketplace.endpoint_id) or {}).get(\"capability\")\n    routed = f\"treg.{capability}\" if capability else None\n    return routed if routed in by_id else None\n\n\nasync def run_call_surface(rest: str, request: Request, caller: Caller, *, prefix: str, finish,\n                           headers=None) -> Response:\n    \"\"\"One call through the whole call road: the caller's identity stashed for the refusal fallback,\n    the context built from the raw request, `execute_call`, and the same bookkeeping on every exit.\n    Every call surface (`/call/`, `/catalog/call/`, `/table/`) goes through here; only `finish`,\n    which turns the answer into the HTTP response, differs. `finish(request, context, upstream,\n    rest)` runs inside the same try, so a fault there is audited and released like any other.\n    `headers`, when given, replaces the request's raw headers for the upstream call (`/table/` asks\n    the provider for uncompressed bytes); `/call/` never passes it.\"\"\"\n    enter_call(request, caller)\n    # Faithful-relay: use the RAW request path, not Starlette's decoded path param. Decoding is\n    # lossy — an encoded slash (`%2f`) in `rest` would become a real `/` and change the upstream\n    # route (npm's scoped publish `PUT /@scope%2fname` 404s as `/@scope/name`). httpx preserves\n    # valid percent-escapes, so the original bytes travel through to the upstream one-to-one.\n    raw_path = request.scope.get(\"raw_path\")\n    if raw_path:\n        _, sep, raw_rest = raw_path.decode(\"ascii\", \"replace\").partition(prefix)\n        if sep:\n            rest = raw_rest\n    call_input = CallInput(\n        method=request.method,\n        raw_rest=rest,\n        raw_headers=tuple(request.headers.raw) if headers is None else tuple(headers),\n        query_items=tuple(request.query_params.multi_items()),\n        raw_query=request.url.query or \"\",\n        body=_HttpRequestBody(request),\n        caller=CallerSnapshot.capture(caller),\n        client_ip=_client_ip(request),\n        catalog_only=bool(getattr(request.state, \"catalog_only\", False)),\n    )\n    return await run_call_input(request, caller, call_input, finish=finish, rest=rest)\n\n\ndef enter_call(request: Request, caller: Caller) -> None:\n    \"\"\"Who is calling, stashed before anything can refuse: the root log and the refusal fallback.\"\"\"\n    org_traffic.identify(request.scope, caller.org_id, enter=True,\n                         api_key_id=caller.api_key.id if caller.api_key else None)\n    # Identity for the refusal fallback in `_mark_treg_own_errors`: a raise anywhere below (unknown\n    # tool, deny rule, daily cap) leaves this handler without an audit row, and the exception handler\n    # is the one place every such refusal passes through - but it has no Caller of its own.\n    request.state.call_identity = (caller.org_id, caller.email)\n    # The pin too: a pinned caller's history is filtered on it, and a refusal (403 on a pin\n    # mismatch above all) is the row they most need to see while integrating.\n    request.state.call_pins = dict(caller.membership.pinned_tags or {}) or None\n    request.state.call_team_slug = caller.org.slug\n    request.state.call_key = (\n        caller.api_key.id if caller.api_key else None,\n        caller.api_key.name if caller.api_key else None,\n        caller.api_key.safe_prefix if caller.api_key else None,\n    )\n\n\nasync def run_call_input(request: Request, caller: Caller, call_input: CallInput, *, finish,\n                         rest: str) -> Response:\n    \"\"\"`run_call_surface` from an already built `CallInput`, after `enter_call`.\"\"\"\n    try:\n        context = create_call_context(call_input)\n    except CallFailure as exc:\n        raise _translate_call_failure(exc) from exc\n    request.state.call_ref = context.call_ref\n    request.state.call_context = context\n    slot = None\n    upstream = None\n    streaming = False\n    try:\n        # Caller is trusted; every root HTTP/MCP call enters here, routing children do not.\n        snapshot = await org_flow_control.check(caller.org_id, context.call_ref)\n        slot = await org_concurrency.acquire(\n            caller.org_id, limit=snapshot.max_in_flight if snapshot else None,\n            version=snapshot.version if snapshot else 0,\n            rate_limit=snapshot.rate_limit if snapshot else None)\n        upstream = await execute_call(context, request.app.state.http)\n        if slot is not None:\n            upstream.close = org_concurrency.cleanup_once(upstream.close)\n        response = await finish(request, context, upstream, rest)\n        if slot is not None and isinstance(response, StreamingResponse):\n            response = _LeasedStreamingResponse(response, slot, upstream.close)\n            streaming = True  # The ASGI response now owns cleanup and slot release.\n        return response\n    except (org_concurrency.AdmissionRejected, org_flow_control.PauseRejected) as exc:\n        raise HTTPException(status_code=exc.status_code, detail=exc.detail,\n                            headers={\"Retry-After\": str(exc.retry_after_s)}) from exc\n    except CallFailure as exc:\n        raise _translate_call_failure(exc) from exc\n    except PoolTimeoutError:\n        # The application-wide handler owns the typed 503 and its db_pool event.\n        raise\n    except Exception:\n        # Starlette still owns the bare 500 response. Record the attempted call before re-raising so\n        # this treg-owned failure is represented once in the same funnel as normal call outcomes.\n        request.state.idem_claim = context.idempotency\n        request.state.call_audited = context.audited\n        request.state.call_cost_micro = context.cost_micro\n        await _stamp_call_exit(\n            request, Response(status_code=500), 500, failure_kind=\"unexpected_exception\")\n        context.idempotency = request.state.idem_claim\n        context.audited = request.state.call_audited\n        raise\n    finally:\n        request.state.idem_claim = context.idempotency\n        request.state.call_audited = context.audited\n        request.state.call_cost_micro = context.cost_micro\n        org_traffic.describe(request.scope, tool_name=context.tool_name,\n                             endpoint_id=context.endpoint_id, replay_of=context.replay_of,\n                             provider=context.provider, credential_tier=context.credential_tier,\n                             refused_by=context.refused_by)\n        if slot is not None and not streaming:\n            await slot.finish(upstream.close if upstream is not None else None)\n\n\n@app.api_route(\n    \"/catalog/call/{rest:path}\",\n    methods=[\"GET\", \"POST\", \"PUT\", \"PATCH\", \"DELETE\", \"HEAD\", \"OPTIONS\"],\n    include_in_schema=False,\n)\nasync def call_catalog_endpoint(\n    rest: str,\n    request: Request,\n    caller: Caller = Depends(require_member),\n):\n    \"\"\"Call one catalog endpoint through the same policy, billing, audit, and relay path as /call.\"\"\"\n    org_traffic.identify(request.scope, caller.org_id,\n                         api_key_id=caller.api_key.id if caller.api_key else None)\n    if not get_settings().claude_connector_enabled:\n        raise HTTPException(status_code=404, detail=\"Claude catalog connector is not enabled\")\n    request.state.catalog_only = True\n    return await call_tool(rest, request, caller)\n"
