      "path": "src/treg/application/call/intake.py",
      "content": "\"\"\"Caller metadata intake for proxied calls.\"\"\"\n\nfrom __future__ import annotations\n\nfrom collections.abc import Awaitable, Callable\nfrom dataclasses import dataclass\n\nfrom sqlalchemy.ext.asyncio import AsyncSession\n\nfrom ...infra.db import session_maker\nfrom ...domain.governance import budgets as budget_policy\nfrom ...domain.identity.access import Caller\nfrom ...caller_metadata import _META_KEY_RE\nfrom .idempotency import (\n    _claim_idempotent,\n    _idem_display,\n    _idempotency_key,\n    _replay_idempotent,\n    _request_fingerprint,\n    _scoped_idempotency_key,\n)\nfrom .types import IdempotencyFailed, IdempotentReplay, IntakeFailed\n\n\n# A builder reselling treg through one token stamps their OWN ids on each call —\n# `X-Treg-Meta: customer=cust_8123, workspace=ws_9` — so they can attribute, budget and invoice their\n# users. Deliberately a HEADER and not a tool argument: a model asked to pass an id drops it somewhere\n# in a chain, and a figure you cannot reconcile is worse than no figure. The builder's backend already\n# sets Authorization on this request; this is the same call site.\nMETA_HEADER = \"x-treg-meta\"\n_META_MAX_HEADER = 512\n\n\n@dataclass(frozen=True)\nclass CallMeta:\n    \"\"\"The parsed tag bag for one call. Built ONCE per request (see call_tool) and read by everyone —\n    idempotency scope, budgets, the ledger and the audit row. A second parse site would be a second\n    chance to disagree about who pays.\"\"\"\n\n    tags: dict[str, str]\n    primary_dim: str = budget_policy.DEFAULT_PRIMARY_DIM\n\n    @property\n    def primary_val(self) -> str:\n        return self.tags.get(self.primary_dim, \"\")\n\n\n_NO_META = CallMeta(tags={})\n\n\ndef _tag_telemetry(meta: CallMeta) -> dict:\n    \"\"\"The tag columns of an audit row, built the one way — the refusal path and the success path\n    both write them and had drifted apart once already.\n\n    `budget_dim` stays blank unless the PRIMARY dimension actually carries a value: a call tagged\n    only on some other key must not claim a primary it never had, or a report grouped by the indexed\n    column would attribute it to the empty value.\n    \"\"\"\n    return {\"budget_dim\": meta.primary_dim if meta.primary_val else \"\",\n            \"budget_val\": meta.primary_val,\n            \"tags\": dict(meta.tags) or None}\n\n\ndef _parse_call_meta(raw_header: str | None, caller: Caller | None = None) -> CallMeta:\n    \"\"\"`X-Treg-Meta: k=v, k=v` → a validated bag. No header means today's behaviour exactly.\n\n    REFUSES rather than repairs. A tag that is silently dropped or truncated is usage that leaves the\n    builder's invoice without anyone noticing, and a truncated id can merge two of their users into one\n    line — so an oversized value is a 422, never a `[:128]`.\n\n    A PINNED token (Membership.pinned_tags) wins over the header for the dimensions it names: a token\n    handed to one customer's machine must not be able to bill another customer. Naming a different\n    value for a pinned dimension is a 403 rather than a silent override — a builder debugging their\n    integration needs to see the disagreement, not discover it in a month of misattributed invoices.\n    \"\"\"\n    pinned = (caller.membership.pinned_tags if caller is not None else None) or {}\n    raw = (raw_header or \"\").strip()\n    if not raw:\n        # An unpinned caller with no header is untagged; a pinned one still attributes to its pin, so\n        # a builder can hand out a scoped token and never touch the header at all.\n        return CallMeta(tags=dict(pinned), primary_dim=budget_policy._primary_dim_of(caller)) if pinned else _NO_META\n    if len(raw.encode()) > _META_MAX_HEADER:\n        raise IntakeFailed(\n            \"metadata_invalid\", status_code=422,\n            detail=f\"X-Treg-Meta is limited to {_META_MAX_HEADER} bytes\")\n    tags: dict[str, str] = {}\n    for segment in raw.split(\",\"):\n        raw_key, sep, raw_value = segment.partition(\"=\")\n        if not sep or not _META_KEY_RE.match(raw_key.strip().lower()):\n            # The SHAPE of the segment, which only this parser can report — everything past here is\n            # the shared storage-key rule.\n            raise IntakeFailed(\n                \"metadata_invalid\", status_code=422,\n                detail=(f\"X-Treg-Meta must be `key=value` pairs; keys are 1-32 chars of [a-z0-9_] \"\n                        f\"(got {segment.strip()!r})\"))\n        try:\n            key, value = budget_policy._validate_tag_pair(\n                raw_key, raw_value, where=\"X-Treg-Meta\")\n        except budget_policy.BudgetPolicyError as exc:\n            raise IntakeFailed(\n                \"metadata_invalid\", status_code=exc.status_code,\n                detail=exc.detail) from exc\n        if key in tags:\n            raise IntakeFailed(\n                \"metadata_invalid\", status_code=422,\n                detail=f\"X-Treg-Meta names {key!r} twice\")\n        tags[key] = value\n    if len(tags) > budget_policy._META_MAX_KEYS:\n        raise IntakeFailed(\n            \"metadata_invalid\", status_code=422,\n            detail=(f\"X-Treg-Meta is limited to {budget_policy._META_MAX_KEYS} keys \"\n                    f\"(got {len(tags)})\"))\n    for dim, pinned_val in pinned.items():\n        if tags.get(dim, pinned_val) != pinned_val:\n            raise IntakeFailed(\n                \"metadata_pin_mismatch\", status_code=403,\n                detail=(f\"this token is pinned to {dim}={pinned_val!r} \"\n                        f\"and cannot bill {tags[dim]!r}\"))\n        tags[dim] = pinned_val\n    return CallMeta(tags=tags, primary_dim=budget_policy._primary_dim_of(caller))\n\n\n@dataclass(frozen=True)\nclass IntakeResult:\n    idempotency_key: str\n    fingerprint: str\n    replay: IdempotentReplay | None\n    claim: tuple[int, str, str] | None\n\n\nasync def prepare_call_intake(\n    *,\n    meta: CallMeta,\n    idempotency_header: str | None,\n    method: str,\n    rest: str,\n    raw_query: str,\n    read_body: Callable[[], Awaitable[bytes]],\n    caller: Caller,\n    enforce_tag_budgets: Callable[[Caller, CallMeta, AsyncSession], Awaitable[None]],\n    call_ref: str,\n) -> IntakeResult:\n    \"\"\"Run the pre-resolve gates in their frozen order using bounded transactions.\"\"\"\n    # Blocked status and the per-tag call count, BEFORE the replay below: a blocked user must neither\n    # take an idempotency lock nor be handed an answer this team cached before they were blocked.\n    async with session_maker() as db:\n        await enforce_tag_budgets(caller, meta, db)\n        await db.commit()\n\n    # A retry the caller has labelled: answer it from what we already returned, before resolving\n    # anything or reaching a provider. Nothing happens without the header.\n    # Scoped by the primary tag: two of a builder's users WILL both send `retry-1`, and without\n    # this the second would be served the first's stored response.\n    key = _scoped_idempotency_key(\n        _idempotency_key(idempotency_header), meta, pinned_tags=caller.membership.pinned_tags)\n    if not key:\n        return IntakeResult(\"\", \"\", None, None)\n\n    body = await read_body()\n    fingerprint = _request_fingerprint(method, rest, body, raw_query)\n    async with session_maker() as db:\n        replay = await _replay_idempotent(key, fingerprint, caller, db)\n        if replay is not None:\n            return IntakeResult(key, fingerprint, replay, None)\n        # Claim it now, before anything reaches a provider. Two retries can arrive together and both\n        # miss the lookup above; the unique constraint is what makes the loser wait instead of making\n        # a second upstream call. A check-then-act in Python would leave exactly the window this\n        # feature exists to close — the same reasoning as the conditional UPDATE in ledger.reserve.\n        if not await _claim_idempotent(key, fingerprint, rest, caller, db, call_ref=call_ref):\n            raise IdempotencyFailed(\n                \"idempotency_in_progress\", status_code=409,\n                detail=(f\"a call with Idempotency-Key {_idem_display(key)!r} \"\n                        \"is already in progress — retry shortly\"))\n    return IntakeResult(key, fingerprint, None, (caller.membership.id, key, call_ref))\n"
    },
    {
      "path": "pyproject.toml",
      "content": "[project]\nname = \"tools-registry\"\nversion = \"0.30.0\"\ndescription = \"A remote registry that turns team skills into shareable, callable tools via a credential-injecting proxy.\"\nreadme = \"README.md\"\nlicense = { file = \"LICENSE\" }\nrequires-python = \">=3.12,<3.14\"  # keep in sync with PYREQ in src/treg/web/install.sh\nauthors = [\n    { name = \"Unclecode\", email = \"unclecode@superdesign.dev\" },\n    { name = \"SuperDesign\" },\n]\nmaintainers = [{ name = \"Unclecode\", email = \"unclecode@superdesign.dev\" }]\nkeywords = [\"registry\", \"cli\", \"proxy\", \"credentials\", \"secrets\", \"api\", \"tools\", \"agents\"]\nclassifiers = [\n    \"Development Status :: 4 - Beta\",\n    \"Environment :: Console\",\n    \"Intended Audience :: Developers\",\n    \"License :: Other/Proprietary License\",\n    \"Operating System :: OS Independent\",\n    \"Programming Language :: Python :: 3.12\",\n    \"Programming Language :: Python :: 3.13\",\n    \"Topic :: Software Development\",\n    \"Topic :: Utilities\",\n]\n# Base install = just the CLI. Light + pure-Python, so `pip install tools-registry` (and Homebrew) are\n# fast. Everything needed to RUN a registry server lives in the `[server]` extra below.\ndependencies = [\n    \"httpx>=0.27,<1\",\n    \"posthog>=7.47.3\",\n    \"questionary>=2.0\",\n    \"toon-format==1.2.0\",\n]\n\n[project.optional-dependencies]\n# The registry SERVER — host your own. The FastAPI app, the DB drivers, and encryption. Not needed to\n# USE the CLI against a hosted registry, only to RUN one. Install with: pip install \"tools-registry[server]\"\nserver = [\n    \"alembic>=1.16.5\",\n    \"fastapi>=0.115\",\n    \"uvicorn[standard]>=0.32\",\n    \"sqlmodel>=0.0.22,<0.0.45\",\n    \"sqlalchemy[asyncio]>=2.0.42\",\n    \"aiosqlite>=0.20\",\n    \"asyncpg>=0.30\",\n    \"cryptography>=43\",\n    \"pydantic-settings>=2.5\",\n    \"pyyaml>=6\",   # the endpoint catalog's data files (src/treg/catalog/*.yaml) — server-side only\n    \"stripe>=12\",  # balance top-ups (src/treg/infra/stripe.py) — the payment rail, server-side only\n    \"mcp>=2\",      # the MCP front door (src/treg/mcp.py) — server-side only; pulls httpx2 ALONGSIDE\n    \"quickjs>=1.19.4\",  # the hub's script sandbox engine (src/treg/hub_sandbox.py) — server-side only\n    # httpx (they coexist), so the light CLI's dependency set is untouched\n    \"redis>=5\",    # the shared key-value store (src/treg/infra/kv.py) — server-side only\n    \"obstore>=0.11,<0.12\",\n    \"numpy>=2.1\",  # find's card vectors: one matrix product per query (application/find_index.py)\n    \"pillow>=11\",  # re-draws uploaded pictures before they are stored (src/treg/infra/imaging.py)\n]\n# The LOCAL PROXY (`treg shell` catching the agent's own outgoing calls). It needs to generate a\n# certificate authority on the machine, and `cryptography` is a compiled package — putting it in the\n# base install would end the light, pure-Python CLI. Install with: pip install \"tools-registry[proxy]\"\n# A self-hoster already has it through [server]. Everything else the proxy uses is asyncio + ssl from\n# the standard library plus httpx, which is already a base dependency.\nproxy = [\n    \"cryptography>=43\",\n]\n\n[project.scripts]\ntreg = \"treg.cli:main\"\n# Scheduled maintainer commands (worker profile) — needs the [server] extra; Render cron calls this.\ntreg-worker = \"treg.worker:main\"\n\n[project.urls]\nHomepage = \"https://treg.to\"\nRepository = \"https://github.com/superdesigndev/treg\"\nIssues = \"https://github.com/superdesigndev/treg/issues\"\n\n[dependency-groups]\ndev = [\n    \"import-linter>=2.13\",\n    \"pytest>=8.3\",\n    \"pytest-asyncio>=0.24\",\n    \"ruff>=0.17.1\",\n    \"tools-registry[server]\",   # the test suite imports the server (api, models, …), so dev pulls it in\n]\ntest = [\n    \"playwright>=1.62.0\",\n]\n\n[tool.uv]\n# uv.lock is `revision = 3`; uv < 0.8.4 silently rewrites it to revision 2 (a ~650-line diff\n# that changes no versions). Refuse to run on an old uv rather than teach everyone to avoid `uv lock`.\nrequired-version = \">=0.12\"\n\n[tool.ruff]\ntarget-version = \"py312\"\nextend-exclude = [\"src/treg/web/dashboard\"]\n\n[tool.ruff.lint]\nselect = [\n    \"E4\", \"E7\", \"E9\", \"F\",  # ruff's defaults: syntax, imports, undefined and unused names\n    \"B\",                    # bugbear: likely bugs\n    \"BLE\",                  # a blind `except Exception` must say why it may swallow everything\n    \"ERA\",                  # no commented-out code\n    \"PGH\",                  # a `type: ignore` names its error code\n    \"RUF100\",               # a `noqa` that suppresses nothing is deleted\n]\nignore = [\n    \"E701\", \"E702\",  # one-line compound statements are house style\n    \"E741\",          # `l` and `I` names are fine in a monospace editor\n    \"B905\",          # `zip(strict=)` changes behavior at each call site; adopt it site by site\n]\n\n[tool.ruff.lint.per-file-ignores]\n\"tests/**\" = [\"F811\"]  # pytest fixtures are imported and then named as parameters\n\n[tool.ruff.lint.flake8-bugbear]\nextend-immutable-calls = [\"fastapi.Depends\", \"fastapi.params.Depends\"]\n\n[tool.importlinter]\nroot_package = \"treg\"\ninclude_external_packages = true\nexclude_type_checking_imports = true\n\n[[tool.importlinter.contracts]]\nname = \"Lightweight CLI modules do not import server dependencies\"\ntype = \"forbidden\"\nsource_modules = [\n    \"treg.cli\",\n    # The views the registry renders and the Python CLI prints: `treg.routers` here is only the\n    # package's own __init__, which the CLI imports on the way to them.\n    \"treg.routers\",\n    \"treg.routers.views\",\n    \"treg.routers.views.account\",\n    \"treg.routers.views.catalog\",\n    \"treg.routers.views.toon\",\n    \"treg.cli_session\",\n    \"treg.cli_analytics\",\n    \"treg.client_notice\",\n    \"treg.convert\",\n    \"treg.skills\",\n    \"treg.providers\",\n    \"treg.localrun\",\n    \"treg.shell\",\n    \"treg.agents\",\n    \"treg.egress\",\n    \"treg.fsjail\",\n]\nforbidden_modules = [\n    \"obstore\",\n    \"PIL\",\n    \"aiosqlite\",\n    \"alembic\",\n    \"asyncpg\",\n    \"cryptography\",\n    \"fastapi\",\n    \"mcp\",\n    \"pydantic\",\n    \"pydantic_core\",\n    \"pydantic_settings\",\n    \"redis\",\n    \"sqlalchemy\",\n    \"sqlmodel\",\n    \"starlette\",\n    \"stripe\",\n    \"uvicorn\",\n    \"yaml\",\n]\nignore_imports = [\n    # ensure_proxy_dependency imports this only after the user invokes the optional proxy feature.\n    \"treg.cli -> cryptography\",\n    # render_grant is a server-only path and imports SQLModel only when the server calls it.\n    \"treg.localrun -> sqlmodel\",\n]\nallow_indirect_imports = true\nunmatched_ignore_imports_alerting = \"error\"\nas_packages = false\n\n[[tool.importlinter.contracts]]\nname = \"Money domain does not depend on best-effort audit\"\ntype = \"forbidden\"\nsource_modules = [\"treg.domain.money\"]\nforbidden_modules = [\"treg.audit\"]\nas_packages = true\n\n[[tool.importlinter.contracts]]\nname = \"Routers do not depend on the legacy API module\"\ntype = \"forbidden\"\nsource_modules = [\"treg.routers\"]\nforbidden_modules = [\"treg.api\"]\nas_packages = true\n\n[[tool.importlinter.contracts]]\nname = \"Identity domain does not depend on outer layers\"\ntype = \"forbidden\"\nsource_modules = [\"treg.domain.identity\"]\nforbidden_modules = [\"treg.api\", \"treg.routers\", \"treg.application\", \"treg.domain.governance\"]\nas_packages = true\n\n[[tool.importlinter.contracts]]\nname = \"Governance domain does not depend on outer layers\"\ntype = \"forbidden\"\nsource_modules = [\"treg.domain.governance\"]\nforbidden_modules = [\"treg.api\", \"treg.routers\", \"treg.application\"]\nas_packages = true\n\n[[tool.importlinter.contracts]]\nname = \"Governance policies do not import web frameworks\"\ntype = \"forbidden\"\nsource_modules = [\"treg.domain.governance\"]\nforbidden_modules = [\"fastapi\", \"starlette\"]\nallow_indirect_imports = true\nas_packages = true\n\n[[tool.importlinter.contracts]]\nname = \"Call application does not depend on HTTP adapters\"\ntype = \"forbidden\"\nsource_modules = [\"treg.application.call\"]\nforbidden_modules = [\"treg.api\", \"treg.bootstrap\", \"treg.routers\", \"fastapi\", \"starlette\"]\nallow_indirect_imports = true\nas_packages = true\n\n[[tool.importlinter.contracts]]\nname = \"Connections domain does not depend on outer layers\"\ntype = \"forbidden\"\nsource_modules = [\"treg.domain.connections\"]\nforbidden_modules = [\n    \"treg.api\",\n    \"treg.bootstrap\",\n    \"treg.routers\",\n    \"treg.application\",\n    \"fastapi\",\n    \"starlette\",\n]\nallow_indirect_imports = true\nas_packages = true\n\n[[tool.importlinter.contracts]]\nname = \"Catalog domain is a leaf: no outer layers, no sibling domains\"\ntype = \"forbidden\"\nsource_modules = [\"treg.domain.catalog\"]\nforbidden_modules = [\n    \"treg.oauth_providers\",  # imports domain.connections; display names arrive through a bootstrap seam\n    \"treg.api\",\n    \"treg.bootstrap\",\n    \"treg.routers\",\n    \"treg.application\",\n    \"treg.domain.connections\",\n    \"treg.domain.governance\",\n    \"treg.domain.identity\",\n    \"treg.domain.money\",\n    \"fastapi\",\n    \"starlette\",\n]\nallow_indirect_imports = true\nas_packages = true\n\n[[tool.importlinter.contracts]]\nname = \"Plugins are pure functions: no I/O and no outer layers\"\ntype = \"forbidden\"\nsource_modules = [\"treg.domain.plugins\"]\nforbidden_modules = [\n    \"treg.api\", \"treg.routers\", \"treg.application\", \"treg.bootstrap\", \"treg.audit\", \"treg.models\",\n    \"treg.infra\", \"treg.config\", \"httpx\", \"sqlmodel\", \"sqlalchemy\", \"redis\", \"obstore\", \"fastapi\",\n    \"starlette\",\n]\nallow_indirect_imports = true\nas_packages = true\n\n[[tool.importlinter.contracts]]\nname = \"Tools domain does not depend on outer layers or unsanctioned domains\"\ntype = \"forbidden\"\nsource_modules = [\"treg.domain.tools\"]\n# tools → connections is the one sanctioned intra-domain edge, so it is absent here.\nforbidden_modules = [\n    \"treg.api\",\n    \"treg.bootstrap\",\n    \"treg.routers\",\n    \"treg.application\",\n    \"treg.domain.catalog\",\n    \"treg.domain.governance\",\n    \"treg.domain.identity\",\n    \"treg.domain.money\",\n    \"fastapi\",\n    \"starlette\",\n]\nallow_indirect_imports = true\nas_packages = true\n\n[[tool.importlinter.contracts]]\nname = \"Upstream infrastructure does not depend on HTTP adapters\"\ntype = \"forbidden\"\nsource_modules = [\"treg.infra.upstream\"]\nforbidden_modules = [\"treg.api\", \"treg.bootstrap\", \"treg.routers\", \"fastapi\", \"starlette\"]\nallow_indirect_imports = true\nas_packages = true\n\n[tool.pytest.ini_options]\nasyncio_mode = \"auto\"\n# asyncpg connections are bound to the event loop that created them. The test engine is module-level,\n# so keep async tests and fixtures on one loop per pytest process instead of returning pooled Postgres\n# connections to a new function-scoped loop. xdist workers remain isolated processes with their own loop.\nasyncio_default_test_loop_scope = \"session\"\nasyncio_default_fixture_loop_scope = \"session\"\n# `scripts/` is standalone tooling, not part of the shipped package (the wheel is `src/treg` only),\n# but tests import from it — `from scripts import catalog_drift`. Only `python -m pytest` puts the\n# working directory on sys.path; CI runs plain `uv run pytest`, where that import is a\n# ModuleNotFoundError at collection. Say it here so both invocations agree, rather than adding\n# `scripts/__init__.py` and changing what the sdist thinks it contains.\npythonpath = [\".\"]\n# Each OpenAPI operation needs its own id; bootstrap splits multi-method routes for the schema.\nfilterwarnings = [\"error:Duplicate Operation ID:UserWarning\"]\n\n[build-system]\nrequires = [\"hatchling\"]\nbuild-backend = \"hatchling.build\"\n\n[tool.hatch.build.hooks.custom]\npath = \"hatch_build.py\"\n\n[tool.hatch.build.targets.sdist]\n# The sdist is PUBLISHED — everything it carries becomes public on PyPI. Hatchling's default is\n# \"every file git does not ignore\", and `.git/info/exclude` is LOCAL-ONLY, so working material kept\n# out of git that way (plan docs, evidence, probe dumps) still lands in the tarball. Caught on the\n# 0.13.0 build: `docs/evidence/overflow-map-2026-08-26` — 127 MB of aggregator catalogs and probe\n# request/response dumps — would have shipped, naming partners we deliberately do not name in\n# public. The 0.11.0 release hit the same class of bug with `.codegraph/`. So the dangerous paths\n# are excluded HERE, in a committed file, rather than trusted to anyone's local ignore rules.\nexclude = [\n  \"docs/evidence\",          # working evidence for a plan — never public\n  \"docs/*-PLAN.md\",         # ditto: plan docs live locally\n  \"/*-PLAN.md\", \"/*-TODO.md\", \"/*-plan.html\",  # root-level working plans and previews\n  \".worktrees\",             # local linked checkouts may contain private or stale material\n  \".import_linter_cache\",   # build cache (nested .gitignore hides it from git, not from hatchling)\n  \".codegraph\",\n  \".lavish\",                # local visual review artifacts, not distributable product assets\n  \"frontend/node_modules\", \"frontend/test-results\", \"frontend/playwright-report\",\n  \"videos\",                 # git-excluded marketing renders\n  \"/src/treg/web/media/**/*.mp4\",  # hosted-page demos stay in Git deployments, not PyPI\n  \"*.db\", \"*.sqlite3\", \"scratch*\", \"body.json\",   # stray local artifacts\n  \".env\", \".env.*\",         # belt and braces: a credential file must never reach a tarball\n]\n\n[tool.hatch.build.targets.wheel]\npackages = [\"src/treg\"]\nexclude = [\n  \"/src/treg/web/media/**/*.mp4\",  # the light CLI must not carry hosted-page demo videos\n]\n# The web/ dir lives inside the treg package