treg.domain.identity\", \"treg.domain.governance\", \"treg.domain.connections\", \"treg.domain.tools\", \"treg.domain.catalog\", \"treg.domain.capacity\", \"treg.domain.money\", \"treg.domain.asynctasks\", \"treg.domain.hub\", \"fastapi\", \"starlette\", \"sqlmodel\", \"sqlalchemy\", \"pydantic\", \"pydantic_settings\", \"yaml\", \"httpx\", \"PIL\", \"obstore\"]\nallow_indirect_imports = true\nas_packages = true\n\n[[tool.importlinter.contracts]]\nname = \"Table domain is a pure stdlib leaf: an answer in, rows and columns out\"\ntype = \"forbidden\"\nsource_modules = [\"treg.domain.table\"]\nforbidden_modules = [\"treg.api\", \"treg.routers\", \"treg.application\", \"treg.bootstrap\", \"treg.audit\", \"treg.models\", \"treg.infra\", \"treg.config\", \"treg.domain.identity\", \"treg.domain.governance\", \"treg.domain.connections\", \"treg.domain.tools\", \"treg.domain.catalog\", \"treg.domain.capacity\", \"treg.domain.money\", \"treg.domain.asynctasks\", \"treg.domain.hub\", \"fastapi\", \"starlette\", \"sqlmodel\", \"sqlalchemy\", \"pydantic\", \"pydantic_settings\", \"yaml\", \"httpx\"]\nallow_indirect_imports = true\nas_packages = true\n\n[[tool.importlinter.contracts]]\nname = \"Capacity domain does not depend on outer layers\"\ntype = \"forbidden\"\nsource_modules = [\"treg.domain.capacity\"]\nforbidden_modules = [\"treg.api\", \"treg.routers\", \"treg.application\", \"treg.bootstrap\", \"fastapi\", \"starlette\", \"treg.audit\"]\nallow_indirect_imports = true\nas_packages = true\n\n[[tool.importlinter.contracts]]\nname = \"Feedback domain does not depend on outer layers or sibling domains\"\ntype = \"forbidden\"\nsource_modules = [\"treg.domain.feedback\"]\nforbidden_modules = [\n    \"treg.api\",\n    \"treg.bootstrap\",\n    \"treg.routers\",\n    \"treg.application\",\n    \"treg.audit\",\n    \"treg.domain.identity\",\n    \"treg.domain.governance\",\n    \"treg.domain.connections\",\n    \"treg.domain.tools\",\n    \"treg.domain.catalog\",\n    \"treg.domain.capacity\",\n    \"treg.domain.money\",\n    \"treg.domain.asynctasks\",\n    \"fastapi\",\n    \"starlette\",\n]\nallow_indirect_imports = true\nas_packages = true\n"
